function bfFixes(){return [
{name:'eqeqeq',find:/([^=!])==([^=])/g,replace:'$1===$2',desc:'== to ==='},
{name:'no-var',find:/\bvar\s+([A-Za-z_$][\w$]*)/g,replace:'let $1',desc:'var to let'},
{name:'dbl-semi',find:/;;+/g,replace:';',desc:'collapse semicolons'}];}
function bfApply(code){var applied=[];var out=code;bfFixes().forEach(function(f){var before=out;out=out.replace(f.find,f.replace);if(out!==before)applied.push(f.name);});return {code:out,applied:applied};}
function bfDiff(a,b){var al=a.split('\n'),bl=b.split('\n');var d=[];var n=Math.max(al.length,bl.length);
for(var i=0;i<n;i++){if(al[i]!==bl[i])d.push({line:i+1,from:al[i]||'',to:bl[i]||''});}return d;}
